function setInstrument(value){state.instrument=value;$('game').classList.toggle('instrument',value);state.zoom=false;camera.fov=value?42:65;camera.updateProjectionMatrix();if(value){state.pos.set(0,0,0);state.yaw=0;state.pitch=Math.atan2(targets[0].aim.y-(stationY+1.75),38);toast('P2 sets your north reference. Aim at its prism and record.');}else{state.pos.set(3,0,3);toast('Walk the site. Return to P1 to take measurements.');}$('scope').hidden=!value;$('crosshair').hidden=value;$('exitInstrument').hidden=!value;$('zoomBtn').hidden=!value;$('joystick').style.visibility=value?'hidden':'';$('zoomBtn').textContent='Zoom 1×';$('stationLabel').textContent=value?'STATION P1 · NORTH REFERENCE':'ON FOOT';instrument.visible=!value;updateUI();}
function record(){if(!state.target){toast('Aim the crosshair at the center of a survey prism.');return;}const p=state.target,r=reading(p);state.records[p.id]={angle:Number(r.angle.toFixed(2)),distance:Number(r.distance.toFixed(2))};toast(`${p.id} recorded · ${r.angle.toFixed(2)}° / ${r.distance.toFixed(2)} m`);state.selected=corners.slice(1).find(p=>state.records[p.id]&&!state.plots[p.id])?.id||p.id;updateUI();drawMini();}
