// The field book uses a north-up, metric plotting surface. World -Z is north.
const bounds={xmin:-15,xmax:80,zmin:-70,zmax:30};
function mapProject(p,w,h,pad=35){const s=Math.min((w-pad*2)/95,(h-pad*2)/100);return {x:pad+(p.x-bounds.xmin)*s,y:pad+(p.z-bounds.zmin)*s,s};}
function mapUnproject(x,y,w,h,pad=35){const s=mapProject({x:0,z:0},w,h,pad).s;return {x:(x-pad)/s+bounds.xmin,z:(y-pad)/s+bounds.zmin};}
function line(ctx,a,b){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}
function baseMap(canvas,mini=false){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,pad=mini?13:42;ctx.clearRect(0,0,w,h);ctx.fillStyle='#ececdb';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#b9c5ac';ctx.lineWidth=mini?.5:1;for(let x=-10;x<=80;x+=10)line(ctx,mapProject({x,z:-70},w,h,pad),mapProject({x,z:30},w,h,pad));for(let z=-70;z<=30;z+=10)line(ctx,mapProject({x:-15,z},w,h,pad),mapProject({x:80,z},w,h,pad));ctx.fillStyle='#536854';ctx.font=`${mini?9:15}px system-ui`;ctx.textAlign='left';ctx.fillText('N',w-25,mini?20:32);ctx.beginPath();ctx.moveTo(w-20,mini?24:40);ctx.lineTo(w-25,mini?37:64);ctx.lineTo(w-20,mini?33:57);ctx.lineTo(w-15,mini?37:64);ctx.closePath();ctx.fill();const scale=mapProject({x:0,z:0},w,h,pad).s;ctx.strokeStyle='#354d3e';ctx.lineWidth=2;line(ctx,{x:pad,y:h-17},{x:pad+20*scale,y:h-17});line(ctx,{x:pad,y:h-21},{x:pad,y:h-13});line(ctx,{x:pad+20*scale,y:h-21},{x:pad+20*scale,y:h-13});ctx.font=`${mini?8:13}px system-ui`;ctx.fillText('0',pad,h-25);ctx.fillText('20 m',pad+20*scale-15,h-25);return {ctx,w,h,pad};}
function dot(ctx,q,text,mini=false,color='#254d3e'){ctx.fillStyle=color;ctx.beginPath();ctx.arc(q.x,q.y,mini?3:6,0,Math.PI*2);ctx.fill();ctx.font=`${mini?10:17}px system-ui`;ctx.fillText(text,q.x+9,q.y-8);}
