function renderNotes(){$('noteList').replaceChildren();for(const p of corners.slice(1)){const r=state.records[p.id],b=document.createElement('button');b.className='note-row'+(state.selected===p.id?' active':'');b.disabled=!r;b.innerHTML=`<b>${p.id}</b><span>${r?r.angle.toFixed(2)+'°':'Not sighted'}</span><span>${r?r.distance.toFixed(2)+' m':'—'}</span><span>${state.plots[p.id]?'✓':''}</span>`;b.onclick=()=>{state.selected=p.id;$('plotAngle').value='';$('plotDistance').value='';renderNotes();drawPlot();};$('noteList').appendChild(b);}$('plotTitle').textContent=`Plot ${state.selected}`;const enabled=!!state.records[state.selected];$('placeBtn').disabled=!enabled;$('plotAngle').disabled=!enabled;$('plotDistance').disabled=!enabled;$('plotStatus').textContent=enabled?`${state.selected} selected · Use its field notes to place it on the map.`:'Measure a corner from P1, then return to plot it.';$('mapDate').textContent=new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}
function drawPlot(){const {ctx,w,h,pad}=baseMap($('plotMap'));const plotted=corners.filter(p=>state.plots[p.id]);ctx.strokeStyle='#466a54';ctx.lineWidth=2;ctx.setLineDash([7,5]);for(let i=1;i<corners.length;i++){const a=state.plots[corners[i-1].id],b=state.plots[corners[i].id];if(a&&b)line(ctx,mapProject(a,w,h,pad),mapProject(b,w,h,pad));}if(plotted.length===5)line(ctx,mapProject(state.plots.P5,w,h,pad),mapProject(state.plots.P1,w,h,pad));ctx.setLineDash([]);for(const p of plotted)dot(ctx,mapProject(state.plots[p.id],w,h,pad),p.id,false,p.id===state.selected?'#bf7432':'#284e3a');if(state.records[state.selected]){const r=Number($('plotAngle').value),d=Number($('plotDistance').value);if($('plotAngle').value!==''&&Number.isFinite(r)&&Number.isFinite(d)&&d>0&&d<=120){const q=mapProject(fromReading(r,d),w,h,pad),o=mapProject({x:0,z:0},w,h,pad);ctx.strokeStyle='#c2975b';ctx.setLineDash([4,5]);line(ctx,o,q);ctx.setLineDash([]);ctx.beginPath();ctx.arc(q.x,q.y,9,0,Math.PI*2);ctx.stroke();}}}
function placePoint(p){if(!state.records[state.selected])return;state.plots[state.selected]={x:p.x,z:p.z};$('result').textContent='';renderNotes();drawPlot();drawMini();$('plotStatus').textContent=`${state.selected} placed. Select another recorded corner, or check your survey.`;}
$('placeBtn').onclick=()=>{const a=Number($('plotAngle').value),d=Number($('plotDistance').value);if($('plotAngle').value===''||$('plotDistance').value===''||!Number.isFinite(a)||!Number.isFinite(d)||a<0||a>=360||d<=0||d>120){$('plotStatus').textContent='Enter an angle from 0 to under 360° and a distance above 0, up to 120 m.';return;}const p=fromReading(a,d);if(p.x<bounds.xmin||p.x>bounds.xmax||p.z<bounds.zmin||p.z>bounds.zmax){$('plotStatus').textContent='That point falls outside this map. Check your angle and distance.';return;}placePoint(p);};for(const id of ['plotAngle','plotDistance'])$(id).addEventListener('input',drawPlot);
$('plotMap').addEventListener('pointerdown',e=>{if(!state.records[state.selected]){$('plotStatus').textContent='Record this corner at P1 before plotting it.';return;}const c=$('plotMap'),r=c.getBoundingClientRect(),p=mapUnproject((e.clientX-r.left)/r.width*c.width,(e.clientY-r.top)/r.height*c.height,c.width,c.height,42);if(p.x<bounds.xmin||p.x>bounds.xmax||p.z<bounds.zmin||p.z>bounds.zmax)return;placePoint(p);});
$('checkBtn').onclick=()=>{const missing=corners.slice(1).filter(p=>!state.plots[p.id]);if(missing.length){$('result').textContent=`Plot ${missing.map(p=>p.id).join(', ')} before checking the complete boundary.`;return;}const errors=corners.slice(1).map(p=>({id:p.id,e:error(p,state.plots[p.id])})),avg=errors.reduce((s,p)=>s+p.e,0)/4,pass=errors.every(p=>p.e<=1.5),score=Math.max(0,Math.round(100-avg*8));$('result').innerHTML=`<strong>${pass?'Survey complete!':'Keep refining your map'} · ${score}/100</strong><br>Average point error: ${avg.toFixed(2)} m. Practice target: every corner within 1.5 m.<br>${errors.map(p=>p.id+': '+p.e.toFixed(2)+' m').join(' · ')}<br>Your plotted area: ${area(corners.map(p=>state.plots[p.id])).toFixed(0)} m².<br>${pass?'Nice work. You turned field observations into a boundary map.':'Select a corner and use its recorded angle and distance to reposition it.'}`;};
// Optional, feature-detected agent access to the same visible field book.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tool={name:'open_survey_notebook',description:'Open the field notebook and return recorded survey observations and plotted points.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(input&&Object.keys(input).length)throw new Error('No parameters are accepted.');if($('helpDialog').open)$('helpDialog').close();if(!$('notebookDialog').open)openNotebook();return {records:state.records,plots:state.plots};}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
updateUI();drawMini();$('helpDialog').showModal();
